<script lang="ts">
  let { percentage = 0, size = 32, strokeWidth = 3 } = $props<{
    percentage: number;
    size?: number;
    strokeWidth?: number;
  }>();

  const radius = $derived((size - strokeWidth) / 2);
  const circumference = $derived(2 * Math.PI * radius);
  const offset = $derived(circumference - (percentage / 100) * circumference);
